<main class="section"><div class="section-head"><div><span class="eyebrow">Verwaltung</span><h1>Verkäuferinnen</h1></div><a class="btn" href="/admin">Dashboard</a></div><form method="get" class="filters"><input name="q" placeholder="Name, E-Mail oder Telefon" value="<?=App\Core\View::e($_GET['q']??'')?>"><button class="btn primary">Suchen</button></form><div class="table-wrap"><table><thead><tr><th>Name</th><th>E-Mail</th><th>Status</th><th>Aufträge</th><th></th></tr></thead><tbody><?php foreach($sellers as $s):?><tr><td><strong><?=App\Core\View::e($s['first_name'].' '.$s['last_name'])?></strong></td><td><?=App\Core\View::e($s['email'])?></td><td><?= $s['deleted_at']?'gelöscht':($s['email_verified_at']?'verifiziert':'unverifiziert') ?></td><td><?= (int)$s['order_count'] ?></td><td><a class="btn" href="/admin/verkaeuferinnen/<?=$s['id']?>">Akte öffnen</a></td></tr><?php endforeach;?></tbody></table></div></main>